package com.saasquatch.intelligence.config; import com.saasquatch.intelligence.entity.*; import com.saasquatch.intelligence.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; @Configuration public class DataSeeder { @Bean CommandLineRunner seed(CompanyRepository companies,CorporateRelationshipRepository rels){return args->{if(rels.count()==0){Company a=companies.findById(1L).orElse(null), b=companies.findById(2L).orElse(null); if(a!=null&&b!=null){CorporateRelationship r=new CorporateRelationship(); r.setCompany(a);r.setRelatedCompany(b);r.setType(RelationshipType.RELATED);r.setEffectiveDate("2026-01-01");r.setDescription("Related-company context supplied for demonstration");rels.save(r);}}};}}